alter table public.properties add column if not exists parcel_number integer; alter table public.properties add column if not exists installments_clear boolean; alter table public.properties add column if not exists canonical_key text; create unique index if not exists properties_canonical_key_uq on public.properties(canonical_key) where canonical_key is not null; create index if not exists properties_parcel_city_idx on public.properties(city,parcel_number) where parcel_number is not null;
